const icons={leaf:'<path d="M19 3C8 3 3 8 5 15c2 6 13 6 14-12Z"/><path d="M5 20 15 9M9 14v-4"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',school:'<path d="m3 9 9-6 9 6M5 9v11h14V9M3 20h18M10 20v-5h4v5M9 10h0M15 10h0"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',edit:'<path d="m15 4 5 5-11 11H4v-5ZM13 6l5 5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',chart:'<path d="M4 3v17h17M8 15l4-6 4 3 5-7"/>',check:'<path d="m5 12 4 4 10-10"/>'};
const ic=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={active:'s1',students:[{id:'s1',name:'林小禾',gender:'女',school:'实验小学',year:'2021',entry:'一年级',grade:'六年级',phone:'13800138000'}],exams:[{id:'e1',student:'s1',name:'六年级开学测评',date:'2026-09-08',note:'新学期，继续保持阅读习惯。',subjects:[{name:'语文',type:'score',max:100,score:88},{name:'数学',type:'score',max:100,score:91},{name:'英语',type:'score',max:100,score:90}]},{id:'e2',student:'s1',name:'九月阶段练习',date:'2026-09-23',note:'',subjects:[{name:'语文',type:'score',max:100,score:92},{name:'数学',type:'score',max:100,score:94},{name:'英语',type:'score',max:100,score:93}]},{id:'e3',student:'s1',name:'十月月考',date:'2026-10-09',note:'数学有进步，继续加油。',subjects:[{name:'语文',type:'score',max:100,score:93},{name:'数学',type:'score',max:100,score:98},{name:'英语',type:'score',max:100,score:95}]}],intents:[{id:'i1',student:'s1',name:'市实验中学',level:'优先考虑',note:'关注校园开放日'},{id:'i2',student:'s1',name:'育才中学',level:'了解中',note:'了解课程与通勤安排'}]};
let db;try{db=JSON.parse(localStorage.getItem('parent-h5-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}
let page='home',subject='语文',draft=null;const app=document.getElementById('app'),overlay=document.getElementById('overlay');
const student=()=>db.students.find(s=>s.id===db.active)||db.students[0];const exams=()=>db.exams.filter(e=>e.student===student().id).sort((a,b)=>b.date.localeCompare(a.date));const intents=()=>db.intents.filter(i=>i.student===student().id);const id=()=>crypto.randomUUID();
function persist(){try{localStorage.setItem('parent-h5-v1',JSON.stringify(db));return true}catch{toast('浏览器存储不可用，记录仅在本次页面中保留');return false}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function navigate(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'})}function closeModal(){overlay.innerHTML='';document.body.style.overflow='';draft=null}
function modal(title,sub,body,foot=''){overlay.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><div><h2>${title}</h2><small>${sub}</small></div><button class="close" data-action="close" aria-label="关闭">×</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-footer">${foot}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';overlay.querySelector('input,select,textarea,button')?.focus()}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}function select(label,name,opts,val){return `<label class="field"><span>${label}</span><select name="${name}">${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}function textArea(label,name,val=''){return `<label class="field"><span>${label}</span><textarea name="${name}" placeholder="选填，补充想记录的信息">${esc(val)}</textarea></label>`}
function total(e){const ss=e.subjects.filter(s=>s.type==='score');return ss.length?ss.reduce((n,s)=>n+Number(s.score),0):null}function signature(e){return e.subjects.every(s=>s.type==='score')?e.subjects.map(s=>`${s.name}:${s.max}`).sort().join('|'):null}
function statsHTML(){let es=exams(),sig=signature(es[0]||{subjects:[]}),same=sig?es.filter(e=>signature(e)===sig):[];return `<div class="stats"><div class="stat"><div class="label">已记录考试</div><strong>${es.length}</strong><small>次</small></div><div class="stat"><div class="label">平均总分</div><strong>${same.length?(same.reduce((n,e)=>n+total(e),0)/same.length).toFixed(1):'—'}</strong><small>分</small></div><div class="stat"><div class="label">最高总分</div><strong>${same.length?Math.max(...same.map(total)):'—'}</strong><small>分</small></div></div><div class="hint">总分仅比较与最近一次考试科目、满分相同的分数制考试。</div>`}
function chartHTML(){let es=exams().reverse(),names=[...new Set(es.flatMap(e=>e.subjects.filter(s=>s.type==='score').map(s=>s.name)))];if(!names.includes(subject))subject=names[0];let points=es.map(e=>({date:e.date,s:e.subjects.find(s=>s.name===subject&&s.type==='score')})).filter(p=>p.s);const px=i=>points.length===1?190:45+i*320/(points.length-1),py=p=>128-Number(p.s.score)/Number(p.s.max)*108;return `<div class="chart-head"><strong>单科成长趋势 <span class="hint">· 得分率</span></strong><div class="chips">${names.map(n=>`<button class="chip ${n===subject?'active':''}" data-action="subject" data-value="${esc(n)}">${esc(n)}</button>`).join('')}</div></div>${points.length?`<svg class="chart" viewBox="0 0 400 165" role="img" aria-label="${esc(subject)}得分率趋势"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a9c478" stop-opacity=".28"/><stop offset="1" stop-color="#a9c478" stop-opacity="0"/></linearGradient></defs>${[0,50,100].map(v=>`<line x1="40" x2="385" y1="${128-v*1.08}" y2="${128-v*1.08}" stroke="#edf0e8" stroke-dasharray="3 4"/><text x="5" y="${132-v*1.08}" fill="#a1aa9e" font-size="9">${v}%</text>`).join('')}<path d="M${px(0)},128 ${points.map((p,i)=>`L${px(i)},${py(p)}`).join(' ')} L${px(points.length-1)},128Z" fill="url(#shade)"/><polyline points="${points.map((p,i)=>`${px(i)},${py(p)}`).join(' ')}" fill="none" stroke="#71954b" stroke-width="2.5" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${px(i)}" cy="${py(p)}" r="4" fill="white" stroke="#71954b" stroke-width="2"/><text x="${px(i)}" y="${py(p)-12}" text-anchor="middle" font-size="10" fill="#456739">${Math.round(p.s.score/p.s.max*100)}%</text>${(points.length<=5||i===0||i===points.length-1)?`<text x="${px(i)}" y="155" text-anchor="middle" font-size="9" fill="#919c8e">${p.date.slice(5).replace('-','/')}</text>`:''}`).join('')}</svg>`:'<div class="empty">记录分数制成绩后，这里会展示成长趋势。</div>'}`}
function examHTML(e){let d=e.date.split('-');return `<button class="exam" data-action="exam-detail" data-id="${e.id}"><div class="datebox"><b>${d[2]}</b><span>${Number(d[1])}月</span></div><div class="exam-content"><strong>${esc(e.name)}</strong><small>${e.subjects.map(s=>`${esc(s.name)} ${s.type==='score'?s.score:esc(s.grade)}`).join(' · ')}</small></div><div class="exam-total">${total(e)??'—'}<small>${e.subjects.some(s=>s.type==='grade')?'分数科目合计':'总分'}</small></div></button>`}
function profileHTML(){let s=student();return `<div class="card"><div class="profile-top"><div class="avatar">${esc(s.name.slice(-1))}</div><div><h3>${esc(s.name)}</h3><span class="tag">${esc(s.grade)}</span></div><button class="text-btn" style="margin-left:auto" data-action="edit-student">${ic('edit')}<span class="sr"> 编辑</span></button></div><div class="profile-info"><div><small>就读学校</small><span>${esc(s.school)}</span></div><div><small>入学信息</small><span>${esc(s.year)}年 · ${esc(s.entry)}</span></div><div><small>学生性别</small><span>${esc(s.gender)}</span></div><div><small>家长联系方式</small><span>${esc(s.phone)}</span></div></div></div>`}
function schoolHTML(i){return `<div class="school-row"><div class="tile-icon orange">${ic('school')}</div><div><strong>${esc(i.name)}</strong><small>${esc(i.note)||'暂无备注'}</small></div><button class="tag" data-action="edit-intent" data-id="${i.id}" aria-label="编辑${esc(i.name)}">${esc(i.level)} ›</button></div>`}
const art=`<svg class="hero-art" viewBox="0 0 300 240" aria-hidden="true"><g class="backleaf" stroke="#98b980" fill="none" stroke-width="1.5"><path d="M215 205Q235 130 253 80M237 139Q208 122 216 103Q243 111 237 139M245 110Q275 111 272 89Q250 84 245 110M227 170Q198 154 202 134Q232 142 227 170"/></g><ellipse cx="161" cy="211" rx="91" ry="12" fill="#194a39"/><g transform="rotate(-10 142 143)"><rect x="65" y="64" width="145" height="136" rx="9" fill="#dcebaa"/><rect x="77" y="56" width="133" height="136" rx="6" fill="#f5f3db"/><path d="M93 56v136" stroke="#d3d5b8"/><path d="M113 82h65M113 97h49M113 161h69" stroke="#d7dbc7" stroke-width="4" stroke-linecap="round"/><path d="m116 144 19-18 17 7 24-24" stroke="#689056" stroke-width="4" fill="none" stroke-linecap="round"/><circle cx="176" cy="109" r="5" fill="#689056"/></g><g transform="rotate(24 219 163)"><rect x="211" y="100" width="12" height="91" rx="3" fill="#deb883"/><path d="m211 188 6 17 6-17" fill="#f0dcc0"/><path d="m214 198 3 7 3-7" fill="#254d3c"/><rect x="211" y="100" width="12" height="12" rx="3" fill="#f0e6cd"/></g><path d="m45 56 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" fill="#dcebaa" opacity=".8"/><circle cx="230" cy="52" r="4" fill="#9dbb82"/></svg>`;
function home(){let s=student();return `<div class="greeting home-header"><div><div class="eyebrow">EVERY LITTLE STEP COUNTS</div><h1>记录点滴，看见成长</h1><div class="subtitle">陪伴 ${esc(s.name)}，一起走好每一步。</div></div>${switcher()}</div><section class="hero"><div class="hero-copy"><div class="eyebrow">孩子的进步，值得被记住</div><h2>每一次努力<br>都有迹可循。</h2><p>记下这次成绩，留住成长的一个瞬间。</p><button class="primary" data-action="add-exam">${ic('plus')} 记一次成绩 ${ic('arrow')}</button></div>${art}</section><div class="actions"><button class="action" data-action="edit-student"><span class="tile-icon">${ic('user')}</span><span><strong>孩子的档案</strong><small>查看与完善基本信息</small></span></button><button class="action" data-action="add-intent"><span class="tile-icon orange">${ic('school')}</span><span><strong>添加意向学校</strong><small>记录下一站的期待</small></span></button></div><div class="layout"><div><div class="section-head"><h2>成长概览</h2><span class="hint">${esc(s.grade)} · 全部记录</span></div><div class="card">${statsHTML()}${chartHTML()}</div><div class="section-head"><h2>最近的成绩</h2><button class="text-btn" data-action="nav" data-value="records">查看全部 ›</button></div><div class="card">${exams().slice(0,3).map(examHTML).join('')||'<div class="empty">还没有考试记录，记下第一次成绩吧。</div>'}</div></div><aside><div class="section-head"><h2>学生档案</h2><button class="text-btn" data-action="pick-student">切换孩子 ›</button></div>${profileHTML()}<div class="section-head"><h2>心仪的学校</h2><button class="text-btn" data-action="nav" data-value="intents">管理 ›</button></div><div class="card">${intents().map(schoolHTML).join('')||'<div class="empty">还没有意向学校，慢慢探索下一站。</div>'}</div><div class="note">${ic('shield')}<span>每一份记录，都属于孩子的成长档案。<br>当前为体验原型，填写内容保存在本机浏览器。</span></div></aside></div>`}
function switcher(){return `<button class="switcher" data-action="pick-student"><span class="avatar">${esc(student().name.slice(-1))}</span>${esc(student().name)} ${ic('down')}</button>`}
function render(){let body;if(page==='home')body=home();if(page==='records')body=`<div class="greeting page-title"><div><div class="eyebrow">GROWTH JOURNAL</div><h1>每一步，都算数</h1><div class="subtitle">${esc(student().name)} · 共 ${exams().length} 次考试记录</div></div>${switcher()}</div><div class="card wide-card">${statsHTML()}${chartHTML()}</div><div class="section-head"><h2>全部考试</h2><button class="primary" data-action="add-exam">${ic('plus')} 录入成绩</button></div><div class="card">${exams().map(examHTML).join('')||'<div class="empty">还没有记录，点击「录入成绩」开始。</div>'}</div>`;if(page==='intents')body=`<div class="greeting page-title"><div><div class="eyebrow">THE NEXT CHAPTER</div><h1>期待下一站</h1><div class="subtitle">为 ${esc(student().name)}，记录心仪的学校。</div></div>${switcher()}</div><div class="section-head"><h2>意向学校 · ${intents().length}</h2><button class="primary" data-action="add-intent">${ic('plus')} 添加学校</button></div><div class="card">${intents().map(schoolHTML).join('')||'<div class="empty">还没有意向学校，点击「添加学校」开始。</div>'}</div><div class="note">${ic('school')}意向可以随时调整。添加学校后，点击意向标签即可修改或删除。</div>`;if(page==='account')body=`<div class="page-title"><div class="eyebrow">YOUR FAMILY SPACE</div><h1>我的家庭档案</h1><div class="subtitle">管理孩子信息，让每一份记录有所归属。</div></div><div class="section-head"><h2>当前学生</h2><button class="text-btn" data-action="pick-student">切换孩子 ›</button></div>${profileHTML()}<div class="card" style="margin-top:20px"><button class="account-row" style="width:100%" data-action="new-student"><span>${ic('plus')} 添加孩子</span><small>已添加 ${db.students.length} 位 ›</small></button><div class="account-row"><span>当前版本</span><small>H5 交互原型</small></div><div class="account-row"><span>数据保存方式</span><small>本机浏览器</small></div><button class="account-row danger" style="width:100%" data-action="reset"><span>重置体验数据</span><span>›</span></button></div><div class="note">${ic('shield')}此版本用于体验录入流程，尚未连接注册登录及后台服务。请使用虚构信息进行体验。</div>`;
app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">${ic('leaf')}</span>成长档案</div><div class="top-right"><span class="demo">体验版</span><span>让成长被看见</span></div></header>${body}<div class="footer-caption">一点一滴，都是成长的足迹</div></div><nav class="bottom-nav" aria-label="主导航">${[['home','home','首页'],['records','book','成绩'],['intents','school','意向'],['account','user','我的']].map(([p,i,l])=>`<button class="nav-item ${page===p?'active':''}" data-action="nav" data-value="${p}" ${page===p?'aria-current="page"':''}>${ic(i)}${l}</button>`).join('')}</nav>`}
function pickStudent(){modal('选择孩子','每位孩子都有独立的成长档案',`${db.students.map(s=>`<button class="picker-row" data-action="select-student" data-id="${s.id}"><span class="avatar">${esc(s.name.slice(-1))}</span><span><strong>${esc(s.name)}</strong><div class="hint">${esc(s.school)} · ${esc(s.grade)}</div></span>${s.id===student().id?`<span class="selected">${ic('check')}</span>`:''}</button>`).join('')}<button class="add-subject" data-action="new-student">＋ 添加一个孩子</button>`)}
function studentForm(isNew){const s=isNew?{year:'2026',entry:'一年级',grade:'一年级',gender:'未填写'}:student();const grades=['一年级','二年级','三年级','四年级','五年级','六年级','初一','初二','初三','高一','高二','高三'];modal(isNew?'添加孩子':'完善孩子的档案','填写一次，成绩与意向自动关联这个孩子',`<form id="student-form">${field('学生姓名 *','name',s.name,'text','maxlength="20" required placeholder="请输入孩子姓名"')}<div class="form-grid">${select('性别','gender',['未填写','男','女'],s.gender)}${select('当前年级 *','grade',grades,s.grade)}</div>${field('就读学校 *','school',s.school,'text','maxlength="80" required placeholder="请输入学校完整名称"')}<div class="form-grid">${field('入学年份 *','year',s.year,'number','min="2000" max="2100" required')}${select('入学年级 *','entry',grades,s.entry)}</div>${field('家长联系方式 *','phone',s.phone,'tel','required pattern="1[3-9][0-9]{9}" maxlength="11" placeholder="11 位手机号"')}<div class="error" id="form-error" role="alert"></div></form>`,`<button class="primary" data-action="save-student" data-value="${isNew?'new':'edit'}">保存档案 ${ic('check')}</button>`)}
function examForm(examId){let e=db.exams.find(e=>e.id===examId);draft=e?structuredClone(e):{id:id(),student:student().id,name:'',date:new Date().toLocaleDateString('sv-SE'),note:'',subjects:['语文','数学','英语'].map(name=>({name,type:'score',max:100,score:''}))};modal(e?'修改考试成绩':'记一次成绩',`${esc(student().name)} · ${esc(student().grade)}，先填写考试，再录入科目`, `<div class="step-note">同一次考试可添加多个科目，每科选择分数或等级。</div><form id="exam-form">${field('考试名称 *','name',draft.name,'text','required maxlength="60" placeholder="例如：六年级期中考试"')}${field('考试日期 *','date',draft.date,'date','required')}<div class="section-head"><h3>科目成绩</h3><span class="hint">可自由增减</span></div><div id="subjects"></div><button type="button" class="add-subject" data-action="add-subject">＋ 添加一个科目</button>${textArea('考试备注','note',draft.note)}<div class="error" id="form-error" role="alert"></div></form>`,`<button class="secondary" data-action="close">取消</button><button class="primary" data-action="save-exam">保存这次成绩 ${ic('check')}</button>`);renderSubjects()}
function renderSubjects(){document.getElementById('subjects').innerHTML=draft.subjects.map((s,i)=>`<div class="subject-card" data-index="${i}"><div class="subject-top"><strong>科目 ${String(i+1).padStart(2,'0')}</strong><div class="segmented"><button type="button" class="${s.type==='score'?'active':''}" data-action="score-type" data-index="${i}" data-value="score">分数</button><button type="button" class="${s.type==='grade'?'active':''}" data-action="score-type" data-index="${i}" data-value="grade">等级</button></div><button type="button" class="danger" data-action="remove-subject" data-index="${i}" aria-label="删除科目 ${i+1}">删除</button></div>${field('科目名称 *',`subject-${i}`,s.name,'text','required maxlength="20" placeholder="例如：语文"')}${s.type==='score'?`<div class="form-grid">${field('满分 *',`max-${i}`,s.max,'number','required min="0.01" max="10000" step="0.01" inputmode="decimal"')}${field('成绩 *',`score-${i}`,s.score,'number','required min="0" max="10000" step="0.01" inputmode="decimal" placeholder="请输入分数"')}</div>`:select('成绩等级 *',`grade-${i}`,['A','B','C','D','优秀','良好','合格','待提高'],s.grade||'A')}</div>`).join('')}
function syncSubjects(){draft.subjects.forEach((s,i)=>{s.name=document.querySelector(`[name="subject-${i}"]`).value;if(s.type==='score'){s.max=document.querySelector(`[name="max-${i}"]`).value;s.score=document.querySelector(`[name="score-${i}"]`).value}else s.grade=document.querySelector(`[name="grade-${i}"]`).value})}
function validForm(f){return f.reportValidity()}function error(msg){document.getElementById('form-error').textContent=msg}
function saveExam(){const f=document.getElementById('exam-form');if(!validForm(f))return;syncSubjects();let names=new Set();for(const s of draft.subjects){s.name=s.name.trim();if(!s.name)return error('请填写科目名称');if(names.has(s.name))return error('同一次考试不能重复填写同一科目');names.add(s.name);if(s.type==='score'){s.max=Number(s.max);s.score=Number(s.score);if(s.score>s.max)return error(`${s.name}成绩不能超过满分`)}}const fd=new FormData(f);draft.name=fd.get('name').trim();if(!draft.name)return error('请填写考试名称');draft.date=fd.get('date');draft.note=fd.get('note').trim();let i=db.exams.findIndex(e=>e.id===draft.id);if(i>=0)db.exams[i]=draft;else db.exams.push(draft);persist();closeModal();render();toast('成绩已保存，成长又多了一笔')}
function detail(examId){const e=db.exams.find(e=>e.id===examId);modal(esc(e.name),`${e.date} · ${esc(student().name)}`,`${e.subjects.map(s=>`<div class="detail-row"><span>${esc(s.name)}</span><span class="detail-score">${s.type==='score'?`${s.score}<small class="hint"> / ${s.max}</small>`:esc(s.grade)}</span></div>`).join('')}<div class="note">${esc(e.note)||'这次考试没有备注。'}</div>`,`<button class="danger" data-action="delete-exam" data-id="${e.id}">删除</button><button class="primary" data-action="edit-exam" data-id="${e.id}">修改成绩 ${ic('edit')}</button>`)}
function intentForm(intentId){const i=db.intents.find(i=>i.id===intentId)||{};modal(i.id?'调整意向学校':'添加意向学校',`为 ${esc(student().name)} 记录下一站的期待`,`<form id="intent-form">${field('意向学校名称 *','name',i.name,'text','required maxlength="80" placeholder="请输入学校完整名称"')}${select('意向等级 *','level',['优先考虑','备选学校','了解中'],i.level||'优先考虑')}${textArea('备注','note',i.note)}<div class="error" id="form-error" role="alert"></div></form>`,`${i.id?`<button class="danger" data-action="delete-intent" data-id="${i.id}">删除</button>`:''}<button class="primary" data-action="save-intent" data-id="${i.id||''}">保存意向 ${ic('check')}</button>`)}
function confirmDelete(type,key){modal('确认删除？','删除后，本机这条记录将无法恢复。','<div class="subtitle">请确认是否继续。</div>',`<button class="secondary" data-action="close">取消</button><button class="primary" data-action="confirm-delete" data-value="${type}" data-id="${key}">确认删除</button>`)}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,k=b.dataset.id,v=b.dataset.value;switch(a){case'nav':navigate(v);break;case'close':closeModal();break;case'subject':subject=v;render();break;case'pick-student':pickStudent();break;case'select-student':db.active=k;persist();closeModal();render();break;case'new-student':studentForm(true);break;case'edit-student':studentForm(false);break;case'save-student':{let f=document.getElementById('student-form');if(!validForm(f))return;let d=Object.fromEntries(new FormData(f));d.name=d.name.trim();d.school=d.school.trim();if(!d.name||!d.school)return error('姓名和学校不能为空');if(v==='new'){d.id=id();db.students.push(d);db.active=d.id}else Object.assign(student(),d);persist();closeModal();render();toast('孩子的档案已保存');break}case'add-exam':examForm();break;case'edit-exam':examForm(k);break;case'exam-detail':detail(k);break;case'add-subject':syncSubjects();draft.subjects.push({name:'',type:'score',max:100,score:''});renderSubjects();document.querySelector(`[name="subject-${draft.subjects.length-1}"]`).focus();break;case'remove-subject':if(draft.subjects.length===1)return toast('至少保留一个科目');syncSubjects();draft.subjects.splice(Number(b.dataset.index),1);renderSubjects();break;case'score-type':syncSubjects();{let s=draft.subjects[Number(b.dataset.index)];if(s.type!==v){s.type=v;delete s.grade;delete s.score;delete s.max;if(v==='score'){s.max=100;s.score=''}else s.grade='A'}renderSubjects()}break;case'save-exam':saveExam();break;case'add-intent':intentForm();break;case'edit-intent':intentForm(k);break;case'save-intent':{let f=document.getElementById('intent-form');if(!validForm(f))return;let d=Object.fromEntries(new FormData(f));d.name=d.name.trim();if(!d.name)return error('请填写学校名称');if(db.intents.some(i=>i.student===student().id&&i.name===d.name&&i.id!==k))return error('已添加这所学校，请修改已有意向');if(k)Object.assign(db.intents.find(i=>i.id===k),d);else db.intents.push({...d,id:id(),student:student().id});persist();closeModal();render();toast('意向学校已保存');break}case'delete-exam':confirmDelete('exams',k);break;case'delete-intent':confirmDelete('intents',k);break;case'confirm-delete':db[v]=db[v].filter(x=>x.id!==k);persist();closeModal();render();toast('记录已删除');break;case'reset':modal('重置体验数据？','会清除本机新增内容，恢复示例档案。','<div class="subtitle">建议体验时使用虚构信息。</div>','<button class="secondary" data-action="close">取消</button><button class="primary" data-action="confirm-reset">确认重置</button>');break;case'confirm-reset':db=structuredClone(seed);persist();closeModal();render();toast('已恢复示例数据');break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&overlay.firstChild){let list=[...overlay.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='exam-form')saveExam();else overlay.querySelector('.modal-footer .primary')?.click()});render();
